-- generated by permdock rls generate
-- fail-closed: never target a bypass role

-- permdock helpers (database: reads the membership and user_roles tables) sha-256:MUJSNhZbqwKmLun1NrP2ufaLyi04ssjqToVYkuLEqUg
-- policies call them uncorrelated, so Postgres evaluates each once per statement

create schema if not exists "permdock";
revoke all on schema "permdock" from public;
grant usage on schema "permdock" to authenticated;

create table if not exists "permdock".role_permissions (
  role text not null,
  permission text not null,
  grant_key text not null,
  scope text not null check (scope ~ '^[a-z][a-z0-9_]*$'),
  effect text not null default 'allow' check (effect in ('allow', 'deny')),
  primary key (role, grant_key, scope)
);
alter table "permdock".role_permissions enable row level security;
revoke all on table "permdock".role_permissions from anon, authenticated, public;
create or replace function "permdock".permdock_role_grant_keys(p_scope text, p_role text)
returns setof text
language sql
stable
parallel safe
rows 10
set search_path = ''
as $$
  select rp.grant_key from "permdock".role_permissions rp where rp.role = p_role and rp.scope = p_scope
$$;
revoke execute on function "permdock".permdock_role_grant_keys(text, text) from public, anon, authenticated;

insert into "permdock".role_permissions (role, permission, grant_key, scope, effect) values
  ('primary', 'payment.approve', 'payment.approve', 'org', 'allow'),
  ('approver', 'payment.read', 'payment.read', 'org', 'allow')
on conflict (role, grant_key, scope) do update
  set permission = excluded.permission, effect = excluded.effect;
delete from "permdock".role_permissions
where (role, grant_key, scope) not in (values
  ('primary', 'payment.approve', 'org'),
  ('approver', 'payment.read', 'org')
);

create table if not exists "permdock".user_roles (
  user_id text not null,
  role text not null,
  primary key (user_id, role)
);
alter table "permdock".user_roles enable row level security;
revoke all on table "permdock".user_roles from anon, authenticated, public;

create or replace function "permdock".permdock_has(p_grant text)
returns boolean
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select exists (
    select 1
    from "permdock".user_roles ur
    cross join lateral "permdock".permdock_role_grant_keys('global', ur.role::text) rp(grant_key)
    where ur.user_id = (select current_setting('app.user_id', true))
      and rp.grant_key = p_grant
      and not (ur.role::text = any(array['reviewer']::text[]))
  )
$$;
revoke execute on function "permdock".permdock_has(text) from public, anon;
grant execute on function "permdock".permdock_has(text) to authenticated;

create or replace function "permdock".permitted_org_ids(p_grant text)
returns setof text
language sql
stable
security definer
cost 1000
rows 10
parallel safe
set search_path = ''
as $$
  select m."org_id"::text
  from "public"."org_members" m
  join "public"."org_roles" mk on mk."id" = m."role_id"
  cross join lateral "permdock".permdock_role_grant_keys('org', mk."key"::text) rp(grant_key)
  where m."user_id" = (select current_setting('app.user_id', true))
    and rp.grant_key = p_grant
    and not (mk."key"::text = any(array['reviewer']::text[]))
    and (nullif((select current_setting('app.tenant_id', true)), '') is null or m."org_id"::text = nullif((select current_setting('app.tenant_id', true)), ''))
$$;
revoke execute on function "permdock".permitted_org_ids(text) from public, anon;
grant execute on function "permdock".permitted_org_ids(text) to authenticated;

-- org ids a grant key reaches, as one array, for `<column> = any(...)`
create or replace function "permdock".permitted_org_id_array(p_grant text)
returns text[]
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select coalesce(array_agg(i), '{}'::text[]) from "permdock".permitted_org_ids(p_grant) i
$$;
revoke execute on function "permdock".permitted_org_id_array(text) from public, anon;
grant execute on function "permdock".permitted_org_id_array(text) to authenticated;
-- whether a grant key reaches one org
create or replace function "permdock".permdock_org_has(p_grant text, p_tenant text)
returns boolean
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
