-- every declared permission key
create or replace function "permdock".permdock_permission_keys()
returns setof text
language sql
stable
set search_path = ''
as $$
  select k.permission from unnest(array['ledger.read', 'payment.approve', 'payment.read']::text[]) k(permission) order by 1
$$;
revoke execute on function "permdock".permdock_permission_keys() from public, anon;
grant execute on function "permdock".permdock_permission_keys() to authenticated;

create or replace function "permdock".permdock_permission_keys(p_scope text)
returns setof text
language sql
stable
security definer
set search_path = ''
as $$
  select distinct rp.permission
  from "permdock".role_permissions rp
  where rp.scope = p_scope
    and rp.effect = 'allow'
    and rp.permission = any(array['ledger.read', 'payment.approve', 'payment.read']::text[])
  order by 1
$$;
revoke execute on function "permdock".permdock_permission_keys(text) from public, anon;
grant execute on function "permdock".permdock_permission_keys(text) to authenticated;

-- the permission keys a role holds on a scope, with effect allow or deny; a custom role is read for its tenant and, below the first scope, its instance
create or replace function "permdock".permdock_role_permissions(p_role text, p_scope text, p_tenant text default null, p_scope_id text default null)
returns table (permission text, effect text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform p_tenant, p_scope_id; -- only a custom role reads them
  return query
  select distinct rp.permission, rp.effect
  from "permdock".role_permissions rp
  where rp.role = p_role and rp.scope = p_scope
  order by 1, 2;
end;
$$;
revoke execute on function "permdock".permdock_role_permissions(text, text, text, text) from public, anon;
grant execute on function "permdock".permdock_role_permissions(text, text, text, text) to authenticated;

create or replace function "permdock".permdock_trusted_role_permissions(p_role text, p_scope text, p_tenant text default null, p_scope_id text default null)
returns table (permission text, effect text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform p_tenant, p_scope_id; -- only a custom role reads them
  return query
  select distinct rp.permission, rp.effect
  from "permdock".role_permissions rp
  where rp.role = p_role and rp.scope = p_scope
  order by 1, 2;
end;
$$;
revoke execute on function "permdock".permdock_trusted_role_permissions(text, text, text, text) from public, anon, authenticated;

-- the grant keys a permission key reaches on one scope: its unconditional allows, with p_effect 'deny' every deny, and with 'conditioned-allow' or 'conditioned-deny' the allows or denies that carry a row condition
create or replace function "permdock".grant_keys(p_permission text, p_scope text, p_effect text default 'allow')
returns setof text
language sql
stable
set search_path = ''
as $$
  select g.grant_key
  from pg_catalog.jsonb_array_elements_text(coalesce(
    '{"org":{"payment.approve":{"allow":["payment.approve"],"deny":[]},"payment.read":{"allow":["payment.read"],"deny":[]}}}'::jsonb -> p_scope -> p_permission -> p_effect,
    '[]'::jsonb
  )) g(grant_key)
$$;
revoke execute on function "permdock".grant_keys(text, text, text) from public, anon;
grant execute on function "permdock".grant_keys(text, text, text) to authenticated;

-- the helpers by permission key: unconditional allows minus any deny
create or replace function "permdock".permdock_has_permission(p_permission text)
returns boolean
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select exists (select 1 from "permdock".grant_keys(p_permission, 'global') g(grant_key) where "permdock".permdock_has(g.grant_key))
    and not exists (select 1 from "permdock".grant_keys(p_permission, 'global', 'deny') g(grant_key) where "permdock".permdock_has(g.grant_key))
$$;
revoke execute on function "permdock".permdock_has_permission(text) from public, anon;
grant execute on function "permdock".permdock_has_permission(text) to authenticated;

create or replace function "permdock".permitted_org_ids_by_permission(p_permission text)
returns setof text
language sql
stable
security definer
cost 1000
rows 10
parallel safe
set search_path = ''
as $$
  select a.id
  from "permdock".grant_keys(p_permission, 'org') g(grant_key)
  cross join lateral "permdock".permitted_org_ids(g.grant_key) a(id)
  except
  select d.id
  from "permdock".grant_keys(p_permission, 'org', 'deny') g(grant_key)
  cross join lateral "permdock".permitted_org_ids(g.grant_key) d(id)
$$;
revoke execute on function "permdock".permitted_org_ids_by_permission(text) from public, anon;
grant execute on function "permdock".permitted_org_ids_by_permission(text) to authenticated;

-- the permission keys the caller holds on one org: what permdock_has_permission or permitted_org_ids_by_permission answers for each key, in one call
create or replace function "permdock".permitted_org_permission_keys(p_id text)
returns setof text
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
set jit = off
as $$
  with pdk_m(key, scope, effect, grant_key) as (
    values
      ('payment.approve', 'org', 'allow', 'payment.approve'),
      ('payment.read', 'org', 'allow', 'payment.read')
  ),
  pdk_w as (
    select pdk_m.key, pdk_m.scope, pdk_m.effect, pdk_m.grant_key
    from pdk_m
  ),
  pdk_g as (
  select rp.grant_key
  from "permdock".user_roles ur
  cross join lateral "permdock".permdock_role_grant_keys('global', ur.role::text) rp(grant_key)
  where ur.user_id = (select current_setting('app.user_id', true))
    and not (ur.role::text = any(array['reviewer']::text[]))
  ),
  pdk_s as (
    select pdk_i.grant_key
    from (
  select m."org_id"::text, rp.grant_key
  from "public"."org_members" m
  join "public"."org_roles" mk on mk."id" = m."role_id"
  cross join lateral "permdock".permdock_role_grant_keys('org', mk."key"::text) rp(grant_key)
  where m."user_id" = (select current_setting('app.user_id', true))
    and not (mk."key"::text = any(array['reviewer']::text[]))
    and (nullif((select current_setting('app.tenant_id', true)), '') is null or m."org_id"::text = nullif((select current_setting('app.tenant_id', true)), ''))
    ) pdk_i(id, grant_key)
    where pdk_i.id = p_id
  ),
  pdk_h as (
    select pdk_w.key, pdk_w.scope, pdk_w.effect
    from pdk_w
    where (pdk_w.scope = 'global' and pdk_w.grant_key in (select pdk_g.grant_key from pdk_g))
      or (pdk_w.scope = 'org' and pdk_w.grant_key in (select pdk_s.grant_key from pdk_s))
  )
  select pdk_k.key
  from (select distinct pdk_w.key from pdk_w where pdk_w.effect = 'allow') pdk_k
  where (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'deny'))
    or (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'org' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'org' and pdk_h.effect = 'deny'))
  order by 1
$$;
revoke execute on function "permdock".permitted_org_permission_keys(text) from public, anon;
grant execute on function "permdock".permitted_org_permission_keys(text) to authenticated;
create or replace function "permdock".permitted_org_permission_keys(p_id text, p_keys text[])
returns setof text
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
set jit = off
as $$
  with pdk_m(key, scope, effect, grant_key) as (
    values
      ('payment.approve', 'org', 'allow', 'payment.approve'),
      ('payment.read', 'org', 'allow', 'payment.read')
  ),
  pdk_w as (
    select pdk_m.key, pdk_m.scope, pdk_m.effect, pdk_m.grant_key
    from pdk_m
    where pdk_m.key in (select k.key from pg_catalog.unnest(p_keys) k(key))
  ),
  pdk_g as (
  select rp.grant_key
  from "permdock".user_roles ur
