  where m."user_id" = (select current_setting('app.user_id', true))
    and not (mk."key"::text = any(array['reviewer']::text[]))
    and (nullif((select current_setting('app.tenant_id', true)), '') is null or m."org_id"::text = nullif((select current_setting('app.tenant_id', true)), ''))
    ) pdk_i(id, grant_key)
    where pdk_i.id = p_id
  ),
  pdk_h as (
    select pdk_w.key, pdk_w.scope, pdk_w.effect
    from pdk_w
    where (pdk_w.scope = 'global' and pdk_w.grant_key in (select pdk_g.grant_key from pdk_g))
      or (pdk_w.scope = 'org' and pdk_w.grant_key in (select pdk_s.grant_key from pdk_s))
  )
  select pdk_k.key
  from (select distinct pdk_w.key from pdk_w where pdk_w.effect = 'allow') pdk_k
  where (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'deny'))
    or (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'org' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'org' and pdk_h.effect = 'deny'))
  order by 1
$$;
revoke execute on function "permdock".permitted_org_permission_keys(text, text[]) from public, anon;
grant execute on function "permdock".permitted_org_permission_keys(text, text[]) to authenticated;

-- with p_conditioned true, also the instances a conditioned allow reaches, minus only unconditional denies: the caller applies the row condition
create or replace function "permdock".permitted_org_ids_by_permission(p_permission text, p_conditioned boolean)
returns setof text
language sql
stable
security definer
cost 1000
rows 10
parallel safe
set search_path = ''
as $$
  select a.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'org') g(grant_key)
    union all
    select g.grant_key from "permdock".grant_keys(p_permission, 'org', 'conditioned-allow') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_org_ids(g.grant_key) a(id)
  except
  select d.id
  from (
    select g.grant_key from "permdock".grant_keys(p_permission, 'org', 'deny') g(grant_key)
    except
    select g.grant_key from "permdock".grant_keys(p_permission, 'org', 'conditioned-deny') g(grant_key)
    where p_conditioned
  ) g
  cross join lateral "permdock".permitted_org_ids(g.grant_key) d(id)
$$;
revoke execute on function "permdock".permitted_org_ids_by_permission(text, boolean) from public, anon;
grant execute on function "permdock".permitted_org_ids_by_permission(text, boolean) to authenticated;

