  order by 1
$$;
revoke execute on function "permdock".permitted_org_permission_keys_for(text, text) from public, anon, authenticated;
create or replace function "permdock".permitted_org_permission_keys_for(p_user text, p_id text, p_keys text[])
returns setof text
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
set jit = off
as $$
  with pdk_m(key, scope, effect, grant_key) as (
    values
      ('payment.approve', 'org', 'allow', 'payment.approve'),
      ('payment.read', 'org', 'allow', 'payment.read')
  ),
  pdk_w as (
    select pdk_m.key, pdk_m.scope, pdk_m.effect, pdk_m.grant_key
    from pdk_m
    where pdk_m.key in (select k.key from pg_catalog.unnest(p_keys) k(key))
  ),
  pdk_g as (
  select rp.grant_key
  from "permdock".user_roles ur
  cross join lateral "permdock".permdock_role_grant_keys('global', ur.role::text) rp(grant_key)
  where ur.user_id = p_user
    and not (ur.role::text = any(array['reviewer']::text[]))
  ),
  pdk_s as (
    select pdk_i.grant_key
    from (
  select m."org_id"::text, rp.grant_key
  from "public"."org_members" m
  join "public"."org_roles" mk on mk."id" = m."role_id"
  cross join lateral "permdock".permdock_role_grant_keys('org', mk."key"::text) rp(grant_key)
  where m."user_id" = p_user
    and not (mk."key"::text = any(array['reviewer']::text[]))
    ) pdk_i(id, grant_key)
    where pdk_i.id = p_id
  ),
  pdk_h as (
    select pdk_w.key, pdk_w.scope, pdk_w.effect
    from pdk_w
    where (pdk_w.scope = 'global' and pdk_w.grant_key in (select pdk_g.grant_key from pdk_g))
      or (pdk_w.scope = 'org' and pdk_w.grant_key in (select pdk_s.grant_key from pdk_s))
  )
  select pdk_k.key
  from (select distinct pdk_w.key from pdk_w where pdk_w.effect = 'allow') pdk_k
  where (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'global' and pdk_h.effect = 'deny'))
    or (exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'org' and pdk_h.effect = 'allow') and not exists (select 1 from pdk_h where pdk_h.key = pdk_k.key and pdk_h.scope = 'org' and pdk_h.effect = 'deny'))
  order by 1
$$;
revoke execute on function "permdock".permitted_org_permission_keys_for(text, text, text[]) from public, anon, authenticated;

-- the users who hold a permission on one org: its members and the global-role holders for whom the _for helpers answer; no client role may execute it
create or replace function "permdock".permitted_org_users(p_permission text, p_id text)
returns setof text
language sql
stable
security definer
set search_path = ''
as $$
  with pdk_h(user_id, grant_key) as (
  select m."user_id"::text, rp.grant_key
  from "public"."org_members" m
  join "public"."org_roles" mk on mk."id" = m."role_id"
  cross join lateral "permdock".permdock_role_grant_keys('org', mk."key"::text) rp(grant_key)
  where m."org_id" = p_id
    and not (mk."key"::text = any(array['reviewer']::text[]))
  ),
  pdk_g(user_id, grant_key) as (
    select pdk_u.user_id, pdk_k.grant_key
    from (
      select distinct ur.user_id::text
      from "permdock".user_roles ur
      where ur.user_id is not null
    ) pdk_u(user_id)
    cross join lateral (
      select rp.grant_key
      from "permdock".user_roles ur
      cross join lateral "permdock".permdock_role_grant_keys('global', ur.role::text) rp(grant_key)
      where ur.user_id = pdk_u.user_id
        and not (ur.role::text = any(array['reviewer']::text[]))
    ) pdk_k(grant_key)
  )
  select h.user_id from pdk_h h
  where h.user_id is not null
    and h.grant_key in (select g.grant_key from "permdock".grant_keys(p_permission, 'org') g(grant_key))
  except
  select h.user_id from pdk_h h
  where h.grant_key in (select g.grant_key from "permdock".grant_keys(p_permission, 'org', 'deny') g(grant_key))
  union
  (select gh.user_id from pdk_g gh
  where gh.grant_key in (select g.grant_key from "permdock".grant_keys(p_permission, 'global') g(grant_key))
  except
  select gh.user_id from pdk_g gh
  where gh.grant_key in (select g.grant_key from "permdock".grant_keys(p_permission, 'global', 'deny') g(grant_key)))
  order by 1
$$;
revoke execute on function "permdock".permitted_org_users(text, text) from public, anon, authenticated;

-- org: holder counts (min / max), checked at commit
create or replace function "permdock".permdock_holders_org()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ids text[] := '{}';
  v_id text;
  v_key "public"."org_members"."org_id"%type;
  v_total bigint;
  v_count bigint;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    v_ids := v_ids || old."org_id"::text;
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_ids := v_ids || new."org_id"::text;
  end if;
  foreach v_id in array v_ids loop
    continue when v_id is null;
    v_key := v_id;
    select count(*) into v_total from "public"."org_members" m where m."org_id" = v_key;
    select count(distinct m."user_id") into v_count
      from "public"."org_members" m
      join "public"."org_roles" mk on mk."id" = m."role_id"
      where m."org_id" = v_key
        and mk."key"::text = 'primary';
    if v_total > 0 and v_count < 1 then
      raise exception using
        errcode = '23514',
        hint = 'last-holder',
        message = 'permdock: org ' || v_id || ' keeps at least 1 primary';
    end if;
    if v_count > 1 then
      raise exception using
        errcode = '23514',
        hint = 'max-holders',
        message = 'permdock: org ' || v_id || ' has at most 1 primary';
    end if;
    select count(*) into v_total from "public"."org_members" m where m."org_id" = v_key;
    select count(distinct m."user_id") into v_count
      from "public"."org_members" m
      join "public"."org_roles" mk on mk."id" = m."role_id"
      where m."org_id" = v_key
        and mk."key"::text = 'approver';
    if v_count > 2 then
      raise exception using
        errcode = '23514',
        hint = 'max-holders',
        message = 'permdock: org ' || v_id || ' has at most 2 approver';
    end if;
  end loop;
  return null;
end;
$$;
drop trigger if exists "permdock_holders_org" on "public"."org_members";
create constraint trigger "permdock_holders_org"
  after insert or update or delete on "public"."org_members"
  deferrable initially deferred
  for each row execute function "permdock".permdock_holders_org();

-- org: transfer-only roles (primary) keep their holder count per statement
create or replace function "permdock".permdock_transfer_only_org()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_change record;
  v_after bigint;
begin
  if tg_op = 'INSERT' then
    for v_change in
      select c.id, c.role, sum(c.delta) as delta
      from (select n."org_id" as id, nk."key"::text as role, 1 as delta from permdock_new n join "public"."org_roles" nk on nk."id" = n."role_id" where nk."key"::text = any(array['primary']::text[])) c
      group by c.id, c.role
    loop
      continue when v_change.delta = 0 or v_change.id is null;
      select count(distinct m."user_id") into v_after
      from "public"."org_members" m
      join "public"."org_roles" mk on mk."id" = m."role_id"
      where m."org_id" = v_change.id
        and mk."key"::text = v_change.role
        and not (v_change.role = any(array['reviewer']::text[]));
      if v_after > 0 and v_after - v_change.delta > 0 then
        raise exception using
          errcode = '23514',
          hint = 'transfer-only',
          message = 'permdock: ' || v_change.role || ' in org ' || v_change.id || ' moves only by transfer';
      end if;
    end loop;
  elsif tg_op = 'DELETE' then
    for v_change in
      select c.id, c.role, sum(c.delta) as delta
      from (select o."org_id" as id, ok."key"::text as role, -1 as delta from permdock_old o join "public"."org_roles" ok on ok."id" = o."role_id" where ok."key"::text = any(array['primary']::text[])) c
      group by c.id, c.role
    loop
      continue when v_change.delta = 0 or v_change.id is null;
      select count(distinct m."user_id") into v_after
      from "public"."org_members" m
      join "public"."org_roles" mk on mk."id" = m."role_id"
      where m."org_id" = v_change.id
        and mk."key"::text = v_change.role
        and not (v_change.role = any(array['reviewer']::text[]));
      if v_after > 0 and v_after - v_change.delta > 0 then
        raise exception using
          errcode = '23514',
          hint = 'transfer-only',
          message = 'permdock: ' || v_change.role || ' in org ' || v_change.id || ' moves only by transfer';
      end if;
    end loop;
  else
    for v_change in
      select c.id, c.role, sum(c.delta) as delta
      from (select n."org_id" as id, nk."key"::text as role, 1 as delta from permdock_new n join "public"."org_roles" nk on nk."id" = n."role_id" where nk."key"::text = any(array['primary']::text[]) union all select o."org_id" as id, ok."key"::text as role, -1 as delta from permdock_old o join "public"."org_roles" ok on ok."id" = o."role_id" where ok."key"::text = any(array['primary']::text[])) c
      group by c.id, c.role
    loop
      continue when v_change.delta = 0 or v_change.id is null;
      select count(distinct m."user_id") into v_after
      from "public"."org_members" m
      join "public"."org_roles" mk on mk."id" = m."role_id"
      where m."org_id" = v_change.id
        and mk."key"::text = v_change.role
        and not (v_change.role = any(array['reviewer']::text[]));
      if v_after > 0 and v_after - v_change.delta > 0 then
        raise exception using
          errcode = '23514',
          hint = 'transfer-only',
          message = 'permdock: ' || v_change.role || ' in org ' || v_change.id || ' moves only by transfer';
      end if;
    end loop;
  end if;
  return null;
end;
$$;
drop trigger if exists "permdock_transfer_only_org_insert" on "public"."org_members";
create trigger "permdock_transfer_only_org_insert"
  after insert on "public"."org_members"
  referencing new table as permdock_new
  for each statement execute function "permdock".permdock_transfer_only_org();
drop trigger if exists "permdock_transfer_only_org_update" on "public"."org_members";
create trigger "permdock_transfer_only_org_update"
  after update on "public"."org_members"
  referencing old table as permdock_old new table as permdock_new
  for each statement execute function "permdock".permdock_transfer_only_org();
drop trigger if exists "permdock_transfer_only_org_delete" on "public"."org_members";
create trigger "permdock_transfer_only_org_delete"
  after delete on "public"."org_members"
  referencing old table as permdock_old
  for each statement execute function "permdock".permdock_transfer_only_org();

-- who may assign: a held role whose assigns lists p_role, in instance p_scope_id (its scope or an ancestor's); a null p_scope_id assigns a global role, which only global assigners may
create or replace function "permdock".permdock_can_assign(p_role text, p_scope_id text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select current_setting('app.user_id', true))::text, '') <> '' and (p_role <> all (array['primary']::text[]) or ((nullif((select current_setting('app.api_key', true)), '')::jsonb is null or nullif((select current_setting('app.api_key', true)), '')::jsonb = 'null'::jsonb) and coalesce((select current_setting('app.client_id', true)), '') = '' and (nullif((select current_setting('app.act', true)), '')::jsonb is null or nullif((select current_setting('app.act', true)), '')::jsonb = 'null'::jsonb))) and (
    exists (
      select 1 from "public"."org_members" m
      join "public"."org_roles" mk on mk."id" = m."role_id"
      where m."user_id" = (select current_setting('app.user_id', true))
        and m."org_id"::text = p_scope_id
        and (mk."key"::text, p_role) in (values ('primary', 'primary'), ('primary', 'approver'))
        and not (mk."key"::text = any(array['reviewer']::text[]))
    )
  )
$$;
revoke execute on function "permdock".permdock_can_assign(text, text) from public, anon;
grant execute on function "permdock".permdock_can_assign(text, text) to authenticated;

-- who may assign, for a user the caller names: trusted SQL acting later for a stored user; no client role may execute it
create or replace function "permdock".permdock_can_assign_for(p_user text, p_role text, p_scope_id text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(p_user::text, '') <> '' and (
    exists (
      select 1 from "public"."org_members" m
      join "public"."org_roles" mk on mk."id" = m."role_id"
      where m."user_id" = p_user
        and m."org_id"::text = p_scope_id
        and (mk."key"::text, p_role) in (values ('primary', 'primary'), ('primary', 'approver'))
        and not (mk."key"::text = any(array['reviewer']::text[]))
    )
  )
$$;
revoke execute on function "permdock".permdock_can_assign_for(text, text, text) from public, anon, authenticated;

-- whether the caller may assign p_role at instance p_scope_id of p_scope in tenant p_tenant, declared or custom (p_scope 'global' for a platform role)
create or replace function "permdock".permdock_can_assign_any(p_role text, p_tenant text, p_scope text, p_scope_id text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce("permdock".permdock_can_assign(p_role, case when p_scope = 'global' then null else p_scope_id end), false)
$$;
revoke execute on function "permdock".permdock_can_assign_any(text, text, text, text) from public, anon;
grant execute on function "permdock".permdock_can_assign_any(text, text, text, text) to authenticated;

-- whether user p_user may assign p_role at instance p_scope_id of p_scope in tenant p_tenant, declared or custom (p_scope 'global' for a platform role); no client role may execute it
create or replace function "permdock".permdock_can_assign_any_for(p_user text, p_role text, p_tenant text, p_scope text, p_scope_id text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce("permdock".permdock_can_assign_for(p_user, p_role, case when p_scope = 'global' then null else p_scope_id end), false)
$$;
revoke execute on function "permdock".permdock_can_assign_any_for(text, text, text, text, text) from public, anon, authenticated;

alter table "public"."payment" enable row level security;
revoke all on table "public"."payment" from anon, authenticated;
grant select, update on table "public"."payment" to authenticated;

alter table "public"."ledger" enable row level security;
revoke all on table "public"."ledger" from anon, authenticated;
grant select on table "public"."ledger" to authenticated;

drop policy if exists "payment_update" on "public"."payment";
create policy "payment_update"
  on "public"."payment"
  as permissive
  for update
  to authenticated
  using ("org_id" = any(array(select "permdock".permitted_org_ids('payment.approve'))))
  with check ("org_id" = any(array(select "permdock".permitted_org_ids('payment.approve'))));

drop policy if exists "payment_select" on "public"."payment";
create policy "payment_select"
  on "public"."payment"
  as permissive
  for select
  to authenticated
  using ("org_id" = any(array(select "permdock".permitted_org_ids('payment.read'))));

drop policy if exists "ledger_select" on "public"."ledger";
create policy "ledger_select"
  on "public"."ledger"
  as permissive
  for select
  to authenticated
  using ("id" in (select m."ledger_id" from "ledger_members" m where m."user_id" = (select current_setting('app.user_id', true)) and (select mk."key"::text from "public"."org_roles" mk where mk."id" = m."role_id") = any('{reviewer}') and coalesce(m."via"::text, '') = any(array['staff']::text[])));
